package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Moves the claim to its new status: DRAFT to OPEN, OPEN to SETTLED (or PENDING), PENDING to SETTLED (approve) or back
 * to OPEN (reject), DRAFT, OPEN or PENDING to VOID. A voided claim keeps
 * its number (never given again). Settling fixes the claim's due: its amount at its
 * person's grade's rate in force on the claim's date, rounded by its rounding (see Rounding) and at least the sheet's floor (left live when no rate applies),
 * or the figure a statement bound it to, with its late charge as of the sheet's today frozen in (see LateCharge).
 * Opening records who opened the claim; that user cannot settle nor approve it (four eyes). A claim whose due is
 * above the sheet's proof threshold in force on its date (if it has one) cannot be settled nor approved while its proofs
 * count is 0 (checked before the clerk limit, so it never goes PENDING); a due of n/a is within any threshold. A claim dated inside a closed
 * period cannot change status, nor can a deferred claim be settled (see ClaimDue#deferred). A clerk (any user not made a steward) settling a claim whose due is above the sheet's
 * clerk limit, if it has one, makes it PENDING instead (its due left live, not bound by a statement); a due of n/a is
 * within any limit. A steward settles anything. Only a steward approves a PENDING claim (fixing its live figure, late
 * charge included, at that moment) or rejects it (OPEN again, bound again by its statement if one bound it).
 * Only a steward re-settles a SETTLED claim (not one dated inside a closed period): its due is fixed again at the figure
 * it would have today as an OPEN claim bound by no statement (today's rates, grades, floor and late charge).
 */
public class ApplyClaimStatus {
    public void apply(@Val Claim claim, @Val ClaimStatusChange change, PersonRepository people, RateRepository rates,
            PeriodRepository periods, SettingRepository settings, RoleRepository roles, SheetRepository sheets, ClaimRepository claims, Out<Claim> changed, Out<ClaimNumber> number, Out<PreviousDue> previous) throws InvalidClaimStatusException {
        boolean allowed = switch (change.action()) {
            case OPEN -> claim.status() == ClaimStatus.DRAFT;
            case SETTLE -> claim.status() == ClaimStatus.OPEN;
            case APPROVE, REJECT -> claim.status() == ClaimStatus.PENDING;
            case VOID -> claim.status() == ClaimStatus.DRAFT || claim.status() == ClaimStatus.OPEN
                    || claim.status() == ClaimStatus.PENDING;
            case RESETTLE -> claim.status() == ClaimStatus.SETTLED;
        };
        if (!allowed) {
            throw new InvalidClaimStatusException("A " + claim.status() + " claim cannot be made " + change.to());
        }
        if (periods.closedOn(claim.sheetId(), claim.date())) {
            throw new InvalidClaimStatusException("The claim's date is inside a closed period");
        }
        if (change.action() == ClaimAction.SETTLE && ClaimDue.deferred(claim, sheets.today(claim.sheetId()))) {
            throw new InvalidClaimStatusException("A deferred claim cannot be settled until the date it is deferred until");
        }
        boolean steward = RoleRepository.STEWARD.equals(roles.roleOf(claim.sheetId(), change.by()));
        if ((change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE)
                && change.by().equals(claim.openedBy())) {
            throw new InvalidClaimStatusException("The user who opened a claim cannot settle nor approve it");
        }
        if ((change.action() == ClaimAction.APPROVE || change.action() == ClaimAction.REJECT) && !steward) {
            throw new InvalidClaimStatusException("Only a steward approves or rejects a pending claim");
        }
        if (change.action() == ClaimAction.RESETTLE && !steward) {
            throw new InvalidClaimStatusException("Only a steward re-settles a claim");
        }
        ClaimStatus to = change.to();
        LateCharge late = LateCharge.of(claim.sheetId(), sheets, settings, claims);
        BigDecimal settledDue;
        if (change.action() == ClaimAction.RESETTLE) {
            Claim asOpen = new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                    claim.note(), ClaimStatus.OPEN, claim.number(), null, claim.openedBy(), false, null,
                    claim.corrects(), claim.dueBy(), null, claim.proofs());
            settledDue = late.add(asOpen, due(asOpen, people, rates, settings, late.rounding()));
        } else {
            settledDue = to == ClaimStatus.SETTLED ? late.add(claim, due(claim, people, rates, settings, late.rounding())) : claim.due();
        }
        if ((change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE) && settledDue != null
                && claim.proofs() == 0) {
            BigDecimal threshold = settings.proofThreshold(claim.sheetId(), claim.date());
            if (threshold != null && settledDue.compareTo(threshold) > 0) {
                throw new InvalidClaimStatusException("A claim whose due is above the proof threshold needs a proof");
            }
        }
        if (change.action() == ClaimAction.SETTLE && settledDue != null && !steward) {
            BigDecimal limit = settings.clerkLimit(claim.sheetId());
            if (limit != null && settledDue.compareTo(limit) > 0) {
                to = ClaimStatus.PENDING;
                settledDue = null;
            }
        }
        number.set(new ClaimNumber(claim.number()));
        previous.set(new PreviousDue(claim.due()));
        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
                claim.note(), to, claim.number(), settledDue,
                change.action() == ClaimAction.OPEN ? change.by() : claim.openedBy(), claim.stated(), claim.statedDue(), claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs()));
    }

    private static BigDecimal due(Claim claim, PersonRepository people, RateRepository rates, SettingRepository settings,
            Rounding rounding) {
        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
            return claim.statedDue();
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        return person == null ? null : ClaimDue.live(claim, person.gradeOn(claim.date()), rates, settings.floor(claim.sheetId(), claim.date()), rounding);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimDue;
import net.officefloor.hq.app.claim.ClaimLogLine;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Closes an open period, fixing its due-total as it is now: the figures (each due as shown now, with its late charge)
 *  of the claims whose date falls in it and that counted by the status each had at the end of the period's last day,
 *  as its status log records it (a claim added after it does not count), the live rules otherwise applying (a
 *  person's OPEN or PENDING claims dated within a hold of theirs, not bound by a statement, do not, nor do deferred
 *  claims), added up (skipping n/a). Each person's own due-total for the period is fixed
 *  too, for every person on the sheet; the period's is the sum of theirs. Closing a period already closed is refused. */
public class ClosePeriod {
    public void close(@Val Period period, @Val PeriodCloseRequest request, PeriodRepository periods,
            ClaimRepository claims, PersonRepository people, RateRepository rates, SettingRepository settings,
            SheetRepository sheets, ClaimLogRepository log,
            Out<PeriodClose> closed)
            throws InvalidPeriodException {
        if (period.closed()) {
            throw new InvalidPeriodException("The period " + period.name() + " is already closed");
        }
        Map<Long, Person> byId = people.list(period.sheetId()).stream()
                .collect(Collectors.toMap(Person::id, (p) -> p));
        Map<Long, List<ClaimLogLine>> logs = log.bySheet(period.sheetId());
        LateCharge late = LateCharge.of(period.sheetId(), sheets, settings, claims);
        Map<Long, BigDecimal> perPerson = new LinkedHashMap<>();
        for (Long id : byId.keySet()) {
            perPerson.put(id, BigDecimal.ZERO.setScale(2));
        }
        for (Claim c : claims.list(period.sheetId())) {
            Person person = byId.get(c.personId());
            if (c.date().isBefore(period.from()) || c.date().isAfter(period.to())) {
                continue;
            }
            ClaimStatus status = ClaimDue.statusAsOf(logs.getOrDefault(c.id(), List.of()), period.to());
            if (status == null || !ClaimDue.countsLive(ClaimDue.withStatus(c, status), person)
                    || ClaimDue.deferred(c, late.today())) {
                continue;
            }
            BigDecimal figure = person == null ? c.due() : late.add(c, ClaimDue.figure(c, person.gradeOn(c.date()), rates, settings.floor(c.sheetId(), c.date()), late.rounding()));
            if (figure != null) {
                perPerson.merge(c.personId(), figure, BigDecimal::add);
            }
        }
        BigDecimal total = perPerson.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        if (!periods.close(period, total)) {
            throw new InvalidPeriodException("The period " + period.name() + " is already closed");
        }
        periods.fixPersonTotals(period, perPerson);
        closed.set(new PeriodClose(request.by(), total));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.plugin.variable.Val;

/** Reopens a closed period, so its due-total is live again. Only a steward may reopen; reopening a period that is
 *  not closed is refused. */
public class ReopenPeriod {
    public void reopen(@Val Period period, @Val PeriodCloseRequest request, PeriodRepository periods,
            RoleRepository roles) throws InvalidPeriodException {
        if (!RoleRepository.STEWARD.equals(roles.roleOf(period.sheetId(), request.by()))) {
            throw new InvalidPeriodException("Only a steward may reopen a period");
        }
        if (!period.closed() || !periods.reopen(period)) {
            throw new InvalidPeriodException("The period " + period.name() + " is not closed");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Checks a move of a claim to another person on the sheet. Only a steward moves a claim, and only a DRAFT, OPEN or
 * PENDING one: a SETTLED or VOID claim stays. A claim dated inside a closed period, a correction (it belongs with the
 * claim it corrects), a move to the claim's own person, to a person not on the sheet, or to one retired before the
 * claim's date, is refused.
 */
public class ApplyReassign {
    public void apply(@Val Claim claim, @Val ReassignRequest request, PersonRepository people, RoleRepository roles,
            PeriodRepository periods, Out<ClaimReassignment> reassignment) throws InvalidClaimStatusException {
        if (!RoleRepository.STEWARD.equals(roles.roleOf(claim.sheetId(), request.by()))) {
            throw new InvalidClaimStatusException("Only a steward moves a claim");
        }
        if (claim.status() != ClaimStatus.DRAFT && claim.status() != ClaimStatus.OPEN
                && claim.status() != ClaimStatus.PENDING) {
            throw new InvalidClaimStatusException("A " + claim.status() + " claim cannot move");
        }
        if (claim.corrects() != null) {
            throw new InvalidClaimStatusException("A correction stays with the claim it corrects");
        }
        if (periods.closedOn(claim.sheetId(), claim.date())) {
            throw new InvalidClaimStatusException("The claim's date is inside a closed period");
        }
        Person from = people.find(claim.sheetId(), claim.personId());
        Person to = people.find(claim.sheetId(), request.personId());
        if (from == null || to == null || to.id() == from.id()) {
            throw new InvalidClaimStatusException("The claim must move to another person on the sheet");
        }
        if (!to.mayClaimOn(claim.date())) {
            throw new InvalidClaimStatusException("The claim's date is after " + to.name() + "'s retirement");
        }
        reassignment.set(new ClaimReassignment(from, to, request.by()));
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The stored settings: per sheet and key, its values each from a from-date (one undated value for an undated key). */
@Repository
public class SettingRepository {

    /** The most a clerk may settle a claim for; blank for no limit. */
    public static final String CLERK_LIMIT = "clerk-limit";

    /** The most a person's due-total may be; blank for none. */
    public static final String CAP = "cap";

    /** The due above which a claim needs a proof before it is settled or approved; blank for none. */
    public static final String PROOF_THRESHOLD = "proof-threshold";

    /** The least a claim's live due may be; 1.00 until set. */
    public static final String FLOOR = "floor";

    /** The floor a sheet has until one is set. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The days a claim has from its date until it is due by; 14 until set. */
    public static final String TERMS = "terms";

    /** The prefix of a grade's own terms: terms-A, terms-B or terms-C; a grade without its own has the sheet's terms. */
    public static final String TERMS_PREFIX = "terms-";

    /** The terms a sheet has until they are set. */
    public static final int DEFAULT_TERMS = 14;

    /** The percent of an overdue claim's figure added for every full 30 days it is overdue; 0.00 until set. */
    public static final String LATE_PCT = "late-pct";

    /** The late percent a sheet has until one is set. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    /** The date from which a claim's live figures round half to even (before it, half up); blank: the sheet's today. */
    public static final String POLICY_DATE = "policy-date";

    /** The date from which an opened claim is numbered within its period (see ClaimNumbering); blank: off. */
    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";

    /** The from-date an undated setting is stored under: before every date. */
    private static final LocalDate UNDATED = LocalDate.of(1, 1, 1);

    private final JdbcTemplate jdbc;

    private final SheetRepository sheets;

    public SettingRepository(JdbcTemplate jdbc, SheetRepository sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    /** The sheet's settings: every value recorded, by key then from-date. */
    public List<Setting> list(String sheetId) {
        return jdbc.query("SELECT sheet_id, setting_key, setting_value, from_date FROM setting WHERE sheet_id = ?"
                + " ORDER BY setting_key, from_date", SettingRepository::map, sheetId);
    }

    /** The setting's value in force on the date (the one with the latest from-date on or before it), or null when it
     *  has none: nothing is recorded on or before the date, or the value in force is blank. */
    public String value(String sheetId, String key, LocalDate date) {
        List<Setting> found = inForce(sheetId, key, date);
        return found.isEmpty() ? null : found.get(0).value();
    }

    /** The setting recorded in force on the date: none, or the one. */
    private List<Setting> inForce(String sheetId, String key, LocalDate date) {
        return jdbc.query("SELECT sheet_id, setting_key, setting_value, from_date FROM setting WHERE sheet_id = ?"
                + " AND setting_key = ? AND from_date <= ? ORDER BY from_date DESC LIMIT 1", SettingRepository::map,
                sheetId, key, date);
    }

    /** The undated setting's value, or null when it has none. */
    public String value(String sheetId, String key) {
        return value(sheetId, key, UNDATED);
    }

    /** The sheet's clerk limit in force on its today, or null when there is none. */
    public BigDecimal clerkLimit(String sheetId) {
        String value = value(sheetId, CLERK_LIMIT, sheets.today(sheetId));
        return value == null ? null : new BigDecimal(value);
    }

    /** The sheet's cap in force on its today, or null when there is none. */
    public BigDecimal cap(String sheetId) {
        String value = value(sheetId, CAP, sheets.today(sheetId));
        return value == null ? null : new BigDecimal(value);
    }

    /** The sheet's proof threshold in force on the date (a claim's date), or null when there is none. */
    public BigDecimal proofThreshold(String sheetId, LocalDate date) {
        String value = value(sheetId, PROOF_THRESHOLD, date);
        return value == null ? null : new BigDecimal(value);
    }

    /** A due-total held to the cap: the cap when the total is above it (a null cap holds nothing). */
    public static BigDecimal capped(BigDecimal total, BigDecimal cap) {
        return cap != null && total.compareTo(cap) > 0 ? cap.setScale(2) : total;
    }

    /** The sheet's floor in force on the date (a claim's date): the least the claim's live due may be. */
    public BigDecimal floor(String sheetId, LocalDate date) {
        String value = value(sheetId, FLOOR, date);
        return value == null ? DEFAULT_FLOOR : new BigDecimal(value);
    }

    /** The sheet's terms in force on the date: the days a claim of that date has until it is due by. */
    public int terms(String sheetId, LocalDate date) {
        String value = value(sheetId, TERMS, date);
        return value == null ? DEFAULT_TERMS : Integer.parseInt(value);
    }

    /** The terms of a grade in force on the date: its own when one is recorded on or before it, else the sheet's (a
     *  null grade has the sheet's). */
    public int terms(String sheetId, String grade, LocalDate date) {
        String value = grade == null ? null : value(sheetId, TERMS_PREFIX + grade, date);
        return value == null ? terms(sheetId, date) : Integer.parseInt(value);
    }

    /** The sheet's late percent in force on the date (a claim's date): what an overdue claim gains of its figure for
     *  every full 30 days overdue. */
    public BigDecimal latePct(String sheetId, LocalDate date) {
        String value = value(sheetId, LATE_PCT, date);
        return value == null ? DEFAULT_LATE_PCT : new BigDecimal(value);
    }

    /** The sheet's policy date, or null when it is blank (the sheet's today applies). */
    public LocalDate policyDate(String sheetId) {
        String value = value(sheetId, POLICY_DATE);
        return value == null ? null : LocalDate.parse(value);
    }

    /** The sheet's period numbering from-date, or null when it is blank (off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        String value = value(sheetId, PERIOD_NUMBERING_FROM);
        return value == null ? null : LocalDate.parse(value);
    }

    /** Stores the setting from its from-date (null: undated), replacing the value recorded from that date. */
    public Setting save(Setting setting) {
        LocalDate from = setting.from() == null ? UNDATED : setting.from();
        jdbc.update("DELETE FROM setting WHERE sheet_id = ? AND setting_key = ? AND from_date = ?", setting.sheetId(),
                setting.key(), from);
        jdbc.update("INSERT INTO setting (sheet_id, setting_key, setting_value, from_date) VALUES (?, ?, ?, ?)",
                setting.sheetId(), setting.key(), setting.value(), from);
        return setting;
    }

    private static Setting map(ResultSet rs, int n) throws SQLException {
        LocalDate from = rs.getObject("from_date", LocalDate.class);
        return new Setting(rs.getString("sheet_id"), rs.getString("setting_key"), rs.getString("setting_value"),
                UNDATED.equals(from) ? null : from);
    }
}
package net.officefloor.hq.app.role;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The stored roles, one per user name per sheet. A name with no row is a clerk. */
@Repository
public class RoleRepository {

    public static final String CLERK = "clerk";
    public static final String STEWARD = "steward";

    private final JdbcTemplate jdbc;

    public RoleRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The roles given on the sheet, by user name. */
    public List<Role> list(String sheetId) {
        return jdbc.query("SELECT sheet_id, user_name, role FROM user_role WHERE sheet_id = ? ORDER BY user_name",
                RoleRepository::map, sheetId);
    }

    /** The user's role on the sheet: clerk unless given another. */
    public String roleOf(String sheetId, String user) {
        List<String> found = jdbc.queryForList("SELECT role FROM user_role WHERE sheet_id = ? AND user_name = ?",
                String.class, sheetId, user);
        return found.isEmpty() ? CLERK : found.get(0);
    }

    /** Stores the role, replacing the one the user had. */
    public Role save(Role role) {
        jdbc.update("DELETE FROM user_role WHERE sheet_id = ? AND user_name = ?", role.sheetId(), role.user());
        jdbc.update("INSERT INTO user_role (sheet_id, user_name, role) VALUES (?, ?, ?)",
                role.sheetId(), role.user(), role.role());
        return role;
    }

    private static Role map(ResultSet rs, int n) throws SQLException {
        return new Role(rs.getString("sheet_id"), rs.getString("user_name"), rs.getString("role"));
    }
}
